<script setup lang="ts">
import { computed, onMounted, onBeforeUnmount, ref, watch } from 'vue';
import { UtensilsCrossed, ClipboardList, UserRound, Search, MapPin, ShoppingBag, ArrowRight, Check } from 'lucide-vue-next';
import { api, entryName, imageFallback, imageUrl, money } from '../../frontend-shared/api';
import type { Dish, Menu } from '../../frontend-shared/types';
import { memberApi, memberToken, setMemberToken, randomKey, dateLabel, stateLabel, modeLabel, type Data } from '../../frontend-shared/commerce';
import '../../frontend-shared/commerce.css';
import './customer-polish.css';
import MemberCenter from './MemberCenter.vue';
const menu=ref<Menu|null>(null),catalog=ref<Data>({policy:{fulfillments:[]},options:{},open:false});
const member=ref<Data|null>(null),page=ref('menu'),busy=ref(false),loading=ref(true),error=ref(''),notice=ref(''),search=ref(''),category=ref(0);
const selected=ref<Dish|null>(null),selection=ref<Record<string,string[]>>({}),showCart=ref(false);
type Cart={dish_id:number;quantity:number;options:Record<string,string[]>;key:string};
const cart=ref<Cart[]>([]),cartKey=`takeaway-cart:v2:${entryName}`;
try{const raw=JSON.parse(localStorage.getItem(cartKey)||'[]');if(Array.isArray(raw))cart.value=raw.filter(x=>Number.isInteger(x.dish_id)&&Number.isInteger(x.quantity)&&x.quantity>0&&x.quantity<=99&&x.options&&typeof x.options==='object'&&typeof x.key==='string').slice(0,50);}catch{}
watch(cart,v=>{try{localStorage.setItem(cartKey,JSON.stringify(v));}catch{notice.value='浏览器不能保存购物车，请保持当前页面打开。';}},{deep:true});
const fulfillment=ref('pickup'),contact=ref(''),phone=ref(''),note=ref(''),tableNumber=ref(''),address=ref<Data|null>(null),coupon=ref<number|null>(null),claims=ref<Data[]>([]);
const quote=ref<Data|null>(null),requestKey=ref(randomKey()),orders=ref<Data[]>([]),receipt=ref<Data|null>(null);
const dishes=computed(()=>menu.value?.categories.flatMap(c=>c.dishes)||[]);
const filtered=computed(()=>dishes.value.filter(d=>(!category.value||d.category_id===category.value)&&`${d.name}${d.description||''}`.includes(search.value.trim())));
const lines=computed(()=>cart.value.map(c=>{const dish=dishes.value.find(d=>d.id===c.dish_id);let extra=0;const names:string[]=[];for(const g of catalog.value.options[String(c.dish_id)]||[]){for(const id of c.options[g.id]||[]){const o=g.options.find((v:Data)=>v.id===id);if(o){extra+=o.price_cents;names.push(o.name);}}}return {...c,dish,unit:(dish?.price_cents||0)+extra,names};}));
const count=computed(()=>cart.value.reduce((s,l)=>s+l.quantity,0));
const total=computed(()=>lines.value.reduce((s,l)=>s+l.unit*l.quantity,0));
const groups=computed(()=>selected.value?catalog.value.options[String(selected.value.id)]||[]:[]);
const optionsValid=computed(()=>groups.value.every((g:Data)=>{const n=(selection.value[g.id]||[]).length;return n>=g.minimum&&n<=g.maximum;}));
const draft=computed(()=>({items:cart.value.map(({dish_id,quantity,options})=>({dish_id,quantity,options})),fulfillment:fulfillment.value,contact:contact.value,phone:phone.value,note:note.value,table_number:tableNumber.value,coupon_claim_id:coupon.value,address:fulfillment.value==='delivery'&&address.value?Object.fromEntries(['contact','phone','title','detail','latitude','longitude','coordinate_system'].map(k=>[k,address.value![k]])):null}));
watch(draft,()=>{quote.value=null;requestKey.value=randomKey();},{deep:true});
async function action(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function load(){loading.value=true;try{[menu.value,catalog.value]=await Promise.all([api<Menu>('menu'),memberApi('catalog')]);document.title=`${menu.value.store.name} · 点餐`;if(memberToken()){try{updated(await memberApi('members/me'));}catch{setMemberToken('');member.value=null;}}}catch(e){error.value=(e as Error).message;}finally{loading.value=false;}}
function updated(m:Data|null){member.value=m;if(m){if(!contact.value)contact.value=m.name;if(!phone.value)phone.value=m.phone;}else{orders.value=[];claims.value=[];address.value=null;quote.value=null;}}
function chooseAddress(a:Data){address.value=a;contact.value=a.contact;phone.value=a.phone;page.value='checkout';}
async function go(target:string){showCart.value=false;page.value=target;error.value='';notice.value='';window.scrollTo(0,0);if(target==='orders'&&member.value)await action(loadOrders);if(target==='checkout'&&member.value)await action(async()=>{claims.value=(await memberApi('benefits')).claims;if(!address.value){const list=await memberApi<Data[]>('addresses');const a=list.find(a=>a.is_default)||list[0];if(a)address.value={...a.data,id:a.id};}});}
function openDish(d:Dish){if(d.sold_out||d.stock===0)return;selected.value=d;selection.value={};for(const g of catalog.value.options[String(d.id)]||[]){selection.value[g.id]=[];}}
function optionToggle(group:Data,id:string){const arr=selection.value[group.id]||[];if(arr.includes(id))selection.value[group.id]=arr.filter(x=>x!==id);else if(group.maximum===1)selection.value[group.id]=[id];else if(arr.length<group.maximum)selection.value[group.id]=[...arr,id];}
function addSelected(){if(!selected.value||!optionsValid.value)return;const d=selected.value;const options=Object.fromEntries(Object.entries(selection.value).map(([k,v])=>[k,[...v].sort()]));const key=`${d.id}:${JSON.stringify(options)}`;const old=cart.value.find(x=>x.key===key);const existing=cart.value.filter(x=>x.dish_id===d.id).reduce((s,x)=>s+x.quantity,0);if(existing>=Math.min(d.stock??99,99)){notice.value='已达到当前库存或单品数量上限';return;}if(old)old.quantity++;else cart.value.push({dish_id:d.id,quantity:1,options,key});selected.value=null;notice.value='已加入购物车';}
function quantityChange(key:string,delta:number){const row=cart.value.find(c=>c.key===key);if(!row)return;if(row.quantity+delta<1){cart.value=cart.value.filter(c=>c.key!==key);return;}const dish=dishes.value.find(d=>d.id===row.dish_id);const amount=cart.value.filter(c=>c.dish_id===row.dish_id).reduce((s,c)=>s+c.quantity,0);if(delta>0&&amount>=Math.min(dish?.stock??99,99)){notice.value='已达到当前库存或单品数量上限';return;}row.quantity+=delta;}
async function calculate(){if(!member.value){page.value='member';notice.value='请先注册或登录本店会员';return;}await action(async()=>{quote.value=await memberApi('orders/quote','POST',draft.value);});}
async function submit(){if(!quote.value)return;await action(async()=>{const o=await memberApi('orders','POST',{...draft.value,expected_total_cents:quote.value!.total_cents,request_key:requestKey.value});cart.value=[];quote.value=null;receipt.value=o;page.value='orders';await loadOrders();});}
async function loadOrders(){orders.value=await memberApi<Data[]>('orders');}
async function moreOrders(){await action(async()=>{const last=orders.value.at(-1);if(last){const rows=await memberApi<Data[]>(`orders?before=${last.id}`);orders.value.push(...rows);if(!rows.length)notice.value='没有更早的订单';}});}
async function openOrder(o:Data){await action(async()=>{receipt.value=await memberApi(`orders/${o.number}`);orders.value=orders.value.map(row=>row.number===o.number?receipt.value!:row);});}
async function cancelOrder(o:Data){const reason=prompt('请填写取消原因');if(!reason?.trim())return;await action(async()=>{receipt.value=await memberApi(`orders/${o.number}/cancel`,'POST',{status:'CANCELLED',expected_status:o.status,reason});await loadOrders();});}
async function reorder(o:Data){if(cart.value.length&&!confirm('将用这笔订单替换当前购物车，继续吗？'))return;cart.value=o.items.map((i:Data)=>({dish_id:i.dish_id,quantity:i.quantity,options:i.selection||{},key:`${i.dish_id}:${JSON.stringify(i.selection||{})}`}));receipt.value=null;await load();await go('checkout');notice.value='已加入购物车，价格、规格和库存会按当前菜单重新核算。';}
function escape(e:KeyboardEvent){if(e.key==='Escape'){selected.value=null;showCart.value=false;receipt.value=null;}}
onMounted(()=>{load();window.addEventListener('keydown',escape);});onBeforeUnmount(()=>window.removeEventListener('keydown',escape));
</script>
<template>
 <main class="cx-app cx-customer">
  <div class="cx-service-note">在线支付暂未开通 · 订单提交后由门店确认</div>
  <header class="cx-header">
   <div class="cx-store-heading"><div class="cx-store-mark" aria-hidden="true"><UtensilsCrossed :size="27" :stroke-width="1.7" /></div><div class="cx-grow"><span class="cx-eyebrow">热乎的一餐 · 用心做好</span><h1>{{menu?.store.name||'门店点餐'}}</h1></div><span class="cx-store-state" :class="{'is-open':catalog.open}"><i aria-hidden="true"></i>{{catalog.open?'营业中':'休息中'}}</span></div>
   <div v-if="menu?.store.address" class="cx-store-address"><MapPin :size="14" aria-hidden="true" /><span>{{menu.store.address}}</span></div>
   <p v-if="catalog.policy.announcement" class="cx-note cx-announcement">{{catalog.policy.announcement}}</p>
  </header>
  <nav class="cx-nav cx-main-nav" aria-label="顾客导航"><button v-for="item in [['menu','点餐'],['orders','我的订单'],['member','会员中心']]" :key="item[0]" :class="{active:page===item[0]}" :aria-current="page===item[0]?'page':undefined" @click="go(item[0])"><component :is="item[0]==='menu'?UtensilsCrossed:item[0]==='orders'?ClipboardList:UserRound" :size="18" aria-hidden="true" />{{item[1]}}</button><button v-if="page==='checkout'" class="active" aria-current="page"><Check :size="18" aria-hidden="true" />确认订单</button></nav>
  <div class="cx-content"><p v-if="error" class="cx-error" role="alert">{{error}}</p><p v-if="notice" class="cx-note" role="status">{{notice}}</p><div v-if="loading" class="cx-empty" role="status"><span class="cx-loading-dot" aria-hidden="true"></span><p>正在读取门店菜单…</p></div>
  <template v-else-if="page==='menu'">
   <div class="cx-menu-intro"><div><h2>今天，吃点喜欢的</h2><p>挑选菜品，按你的口味搭配。</p></div><span class="cx-menu-count">{{dishes.length}} 道菜品</span></div>
   <div class="cx-search"><Search :size="19" aria-hidden="true" /><label class="cx-sr-only" for="dish-search">搜索菜品</label><input id="dish-search" v-model="search" class="cx-input" type="search" placeholder="搜索菜品或口味"></div>
   <div class="cx-categories" aria-label="菜品分类"><button :class="{active:category===0}" :aria-pressed="category===0" @click="category=0">全部</button><button v-for="c in menu?.categories" :key="c.id" :class="{active:category===c.id}" :aria-pressed="category===c.id" @click="category=c.id">{{c.name}}</button></div>
   <div class="cx-menu-list"><article v-for="d in filtered" :key="d.id" class="cx-dish" :class="{'is-sold-out':d.sold_out||d.stock===0}"><img :src="imageUrl(d.image_url)" :alt="d.name" loading="lazy" @error="imageFallback"><div class="cx-grow"><h3>{{d.name}}</h3><p class="cx-muted cx-dish-description">{{d.description||'用心制作，新鲜呈现'}}</p><div class="cx-row"><div><span class="cx-price">¥{{money(d.price_cents)}}<small v-if="d.requires_options"> 起</small></span><small class="cx-dish-stock">{{d.sold_out||d.stock===0?'暂时售罄':d.stock!==null?'剩余 '+d.stock+' 份':'现点现做'}}</small></div><button class="cx-plus" :aria-label="`选择${d.name}`" :disabled="d.sold_out||d.stock===0" @click="openDish(d)">+</button></div></div></article>
    <div v-if="!filtered.length" class="cx-empty"><Search :size="30" aria-hidden="true" /><h3>没有找到符合条件的菜品</h3><p>换个关键词，或看看全部菜品。</p><button class="cx-secondary" @click="search='';category=0">查看全部菜品</button></div>
   </div>
  </template>
  <template v-if="page==='checkout'"><div class="cx-section-heading"><div><h2>确认这份美味</h2><p>选择用餐方式，核对商品与联系信息。</p></div><span class="cx-tag">订单确认</span></div><div class="cx-card"><h3>用餐与联系信息</h3><div class="cx-options"><label v-for="mode in catalog.policy.fulfillments" :key="mode" :class="{selected:fulfillment===mode}"><input v-model="fulfillment" type="radio" :value="mode"> {{modeLabel(mode)}}</label></div><div v-if="fulfillment==='delivery'"><div v-if="address" class="cx-card"><strong>{{address.title}}</strong><p>{{address.detail}}</p><small>{{address.contact}} · {{address.phone}}</small></div><button class="cx-secondary" @click="go('member')">{{address?'更换收货地址':'在会员中心选择收货地址'}}</button></div><div class="cx-grid"><label class="cx-field"><span>联系人</span><input v-model="contact" maxlength="60" autocomplete="name"></label><label class="cx-field"><span>手机号</span><input v-model="phone" type="tel" maxlength="11" autocomplete="tel"></label></div><label v-if="fulfillment==='dine_in'" class="cx-field"><span>桌号</span><input v-model="tableNumber" maxlength="30" placeholder="例如 A03"></label><label class="cx-field"><span>备注</span><textarea v-model="note" maxlength="500" placeholder="如有特殊要求，请备注并联系门店确认"></textarea></label><label class="cx-field"><span>优惠券（每笔订单使用一张）</span><select v-model="coupon"><option :value="null">不使用优惠券</option><option v-for="c in claims.filter(c=>c.status==='AVAILABLE'&&new Date(c.snapshot.expires_at).getTime()>Date.now())" :key="c.id" :value="c.id">{{c.snapshot.title}} · 满{{money(c.snapshot.minimum_cents)}}减{{money(c.snapshot.amount_cents)}}</option></select></label></div>
   <div class="cx-card cx-checkout-summary"><div class="cx-row"><h3>已选商品</h3><span class="cx-muted">{{count}} 件</span></div><div v-for="l in lines" :key="l.key" class="cx-card"><div class="cx-row"><div><strong>{{l.dish?.name||'已失效菜品'}}</strong><p class="cx-muted">{{l.names.join(' / ')||'标准份'}}</p></div><strong>¥{{money(l.unit*l.quantity)}}</strong></div><div class="cx-qty"><button :aria-label="`减少${l.dish?.name}`" @click="quantityChange(l.key,-1)">−</button><span>{{l.quantity}}</span><button :aria-label="`增加${l.dish?.name}`" @click="quantityChange(l.key,1)">+</button></div></div><div v-if="!lines.length" class="cx-empty"><ShoppingBag :size="30" aria-hidden="true" /><p>购物车为空，请先挑选菜品。</p><button class="cx-secondary" @click="go('menu')">去挑选菜品</button></div>
   <template v-if="quote"><div v-for="r in [['商品金额',quote.subtotal_cents],['包装费',quote.packaging_cents],['配送费',quote.delivery_cents],['优惠',-quote.discount_cents]]" class="cx-row" style="padding:7px 0"><span>{{r[0]}}</span><span>¥{{money(Number(r[1]))}}</span></div><div class="cx-row" style="border-top:1px solid #e8e1d6;padding-top:12px"><strong>订单合计</strong><strong class="cx-price">¥{{money(quote.total_cents)}}</strong></div><p class="cx-note">在线支付暂未开通，提交后订单为未支付状态。请等待门店确认，付款方式请联系门店。</p><button class="cx-primary" style="width:100%" :disabled="busy" @click="submit">{{busy?'正在提交…':'确认提交订单'}}</button></template><button v-else class="cx-primary" style="width:100%" :disabled="busy||!lines.length" @click="calculate">{{member?'核算金额并确认':'登录后继续'}}</button></div></template>
  <template v-if="page==='orders'"><div class="cx-section-heading"><div><h2>我的订单</h2><p>查看每一份订单的最新进度。</p></div><button class="cx-secondary" :disabled="busy||!member" @click="action(loadOrders)">刷新</button></div><div v-if="!member" class="cx-empty"><ClipboardList :size="32" aria-hidden="true" /><h3>登录后，订单进度一目了然</h3><p>在本店提交的订单会保存在这里。</p><button class="cx-primary" @click="go('member')">去登录</button></div><article v-for="o in orders" :key="o.id" class="cx-card cx-order-card"><div class="cx-row"><strong>{{stateLabel(o.status)}}</strong><span class="cx-tag">未支付</span></div><p class="cx-muted">{{o.number}} · {{modeLabel(o.fulfillment)}}</p><p>{{o.items.map((i:Data)=>`${i.name} ×${i.quantity}`).join('，')}}</p><div class="cx-row"><strong class="cx-price">¥{{money(o.total_cents)}}</strong><button class="cx-secondary" @click="openOrder(o)">查看详情</button></div><small class="cx-muted">{{dateLabel(o.created_at)}}</small></article><div v-if="member&&!orders.length" class="cx-empty"><ShoppingBag :size="32" aria-hidden="true" /><h3>第一份美味，等你挑选</h3><p>还没有订单，挑选喜欢的菜品吧。</p><button class="cx-primary" @click="go('menu')">去点餐</button></div><button v-if="orders.length>=30" class="cx-secondary" :disabled="busy" @click="moreOrders">加载更早订单</button></template>
  <MemberCenter v-if="page==='member'" :member="member" @updated="updated" @address="chooseAddress" />
  </div>
  <div v-if="page==='menu'&&count" class="cx-cartbar"><button class="cx-cart-preview" @click="showCart=true"><span class="cx-cart-icon"><ShoppingBag :size="23" aria-hidden="true" /><span>{{count}}</span></span><span><strong>¥{{money(total)}}</strong><small>已选 {{count}} 件 · 查看购物车</small></span></button><button class="cx-primary" @click="go('checkout')">去结算 <ArrowRight :size="18" aria-hidden="true" /></button></div>
  <div v-if="selected" class="cx-overlay" @click.self="selected=null"><section class="cx-dialog" role="dialog" aria-modal="true" aria-label="选择菜品规格"><div class="cx-dialog-header"><h2>{{selected.name}}</h2><button class="cx-secondary" @click="selected=null">关闭</button></div><img :src="imageUrl(selected.image_url)" :alt="selected.name" style="width:100%;max-height:230px;object-fit:cover;border-radius:15px" @error="imageFallback"><p>{{selected.description}}</p><div v-for="g in groups" :key="g.id" class="cx-card"><h3>{{g.name}} <small class="cx-muted">选 {{g.minimum}}–{{g.maximum}} 项</small></h3><div class="cx-options"><label v-for="o in g.options.filter((o:Data)=>o.enabled)" :key="o.id" :class="{selected:(selection[g.id]||[]).includes(o.id)}"><input type="checkbox" :checked="(selection[g.id]||[]).includes(o.id)" @change="optionToggle(g,o.id)"> {{o.name}} <small v-if="o.price_cents">+¥{{money(o.price_cents)}}</small></label></div></div><p v-if="selected.requires_options&&!groups.length" class="cx-error">门店尚未配置此菜品规格，请选择其他菜品。</p><button class="cx-primary" style="width:100%" :disabled="!optionsValid||(selected.requires_options&&!groups.length)" @click="addSelected">加入购物车</button></section></div>
  <div v-if="showCart" class="cx-overlay" @click.self="showCart=false"><section class="cx-dialog" role="dialog" aria-modal="true" aria-label="购物车"><div class="cx-dialog-header"><h2>购物车</h2><button class="cx-secondary" @click="showCart=false">关闭</button></div><div v-for="l in lines" :key="l.key" class="cx-card"><div class="cx-row"><div><strong>{{l.dish?.name||'已失效菜品'}}</strong><p class="cx-muted">{{l.names.join(' / ')}}</p></div><strong>¥{{money(l.unit*l.quantity)}}</strong></div><div class="cx-qty"><button :aria-label="`减少${l.dish?.name}`" @click="quantityChange(l.key,-1)">−</button>{{l.quantity}}<button :aria-label="`增加${l.dish?.name}`" @click="quantityChange(l.key,1)">+</button></div></div><p v-if="!count" class="cx-empty">购物车已清空，继续挑选喜欢的菜品吧。</p><button class="cx-primary" :disabled="!count" @click="go('checkout')">去结算 · ¥{{money(total)}}</button><button class="cx-secondary" @click="cart=[]">清空购物车</button></section></div>
  <div v-if="receipt" class="cx-overlay" @click.self="receipt=null"><section class="cx-dialog cx-print" role="dialog" aria-modal="true" aria-label="订单详情"><div class="cx-dialog-header"><h2>{{stateLabel(receipt.status)}}</h2><button class="cx-secondary" @click="receipt=null">关闭</button></div><p class="cx-note">订单未支付 · 在线支付暂未开通</p><strong>{{receipt.number}}</strong><p>{{modeLabel(receipt.fulfillment)}} {{receipt.table_number?'· 桌号 '+receipt.table_number:''}}</p><p>{{receipt.contact}} · {{receipt.phone}}</p><p v-if="receipt.address">{{receipt.address.title}} {{receipt.address.detail}}</p><p v-if="receipt.note">备注：{{receipt.note}}</p><div v-for="i in receipt.items" class="cx-card"><div class="cx-row"><strong>{{i.name}} × {{i.quantity}}</strong><strong>¥{{money(i.total_cents)}}</strong></div><small>{{i.options.map((o:Data)=>o.option).join(' / ')}}</small></div><p class="cx-muted">包装 ¥{{money(receipt.packaging_cents)}} · 配送 ¥{{money(receipt.delivery_cents)}} · 优惠 ¥{{money(receipt.discount_cents)}}</p><div class="cx-row"><strong>合计</strong><strong class="cx-price">¥{{money(receipt.total_cents)}}</strong></div><h3>订单进度</h3><div v-for="e in receipt.events" class="cx-event"><strong>{{stateLabel(e.status)}}</strong><p>{{dateLabel(e.at)}} {{e.reason}}</p></div><div class="cx-actions"><button class="cx-primary" @click="reorder(receipt)">再来一单</button><button v-if="receipt.status==='PENDING'" class="cx-danger" :disabled="busy" @click="cancelOrder(receipt)">取消订单</button><button class="cx-secondary" :disabled="busy" @click="openOrder(receipt)">刷新状态</button></div><p v-if="error" class="cx-error">{{error}}</p></section></div>
 </main>
</template>
